// Porter Galaxy: the moving parts of the card (five ringed orbit nodes and four lime points).
// Generated by scripts/cards/gen/galaxy-split.mjs from the same source as public/home/cards/galaxy.webp (dust, spiral, orbits, centre).
// At rest, this overlay on that base is the approved card. Build-up is about 1.3 s.
import { EASE, type CardMotion } from './index';

const svg = "<g data-n data-c=\"293.55 154.18\"><circle cx=\"305.7\" cy=\"154.2\" r=\"1\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"297.3\" cy=\"160\" r=\"1\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"283.7\" cy=\"157.8\" r=\"1\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"283.7\" cy=\"150.6\" r=\"1\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"297.3\" cy=\"148.4\" r=\"1\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><ellipse cx=\"293.6\" cy=\"154.2\" rx=\"12.2\" ry=\"6.1\" fill=\"none\" stroke=\"#7FB6C6\" stroke-width=\".6\" stroke-opacity=\".45\"></ellipse><circle cx=\"293.6\" cy=\"154.2\" r=\"3.5\" fill=\"#DCE9F0\"></circle><circle cx=\"293.6\" cy=\"154.2\" r=\"6.9\" fill=\"none\" stroke=\"#DCE9F0\" stroke-width=\".8\" stroke-opacity=\".7\"></circle></g><g data-n data-c=\"419.18 141.18\"><circle cx=\"429.3\" cy=\"149.1\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"413.2\" cy=\"150.1\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"401.5\" cy=\"144.4\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"403.2\" cy=\"136.3\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"416.9\" cy=\"131.9\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"432.3\" cy=\"134.5\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><circle cx=\"437.9\" cy=\"142.1\" r=\"1.1\" fill=\"#DCE9F0\" opacity=\"0.8\"></circle><ellipse cx=\"419.2\" cy=\"141.2\" rx=\"18.8\" ry=\"9.4\" fill=\"none\" stroke=\"#7FB6C6\" stroke-width=\".6\" stroke-opacity=\".45\"></ellipse><circle cx=\"419.2\" cy=\"141.2\" r=\"4\" fill=\"#DCE9F0\"></circle><circle cx=\"419.2\" cy=\"141.2\" r=\"7.8\" fill=\"none\" stroke=\"#DCE9F0\" stroke-width=\".8\" stroke-opacity=\".7\"></circle></g><g data-n data-c=\"414.96 70.95\"><circle cx=\"411.1\" cy=\"75.2\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"406.5\" cy=\"73\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"405.9\" cy=\"69.8\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"409.5\" cy=\"67.1\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"415.7\" cy=\"66.3\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"421.5\" cy=\"67.6\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"424.3\" cy=\"70.5\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"422.7\" cy=\"73.6\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><circle cx=\"417.4\" cy=\"75.5\" r=\"0.8\" fill=\"#DCE9F0\" opacity=\"0.6\"></circle><ellipse cx=\"415\" cy=\"71\" rx=\"9.4\" ry=\"4.7\" fill=\"none\" stroke=\"#7FB6C6\" stroke-width=\".6\" stroke-opacity=\".45\"></ellipse><circle cx=\"415\" cy=\"71\" r=\"2.7\" fill=\"#DCE9F0\"></circle><circle cx=\"415\" cy=\"71\" r=\"5.3\" fill=\"none\" stroke=\"#DCE9F0\" stroke-width=\".8\" stroke-opacity=\".7\"></circle></g><g data-n data-c=\"222.85 155.16\"><circle cx=\"208.2\" cy=\"156.2\" r=\"0.9\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"216.3\" cy=\"148.5\" r=\"0.9\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"233.5\" cy=\"150\" r=\"0.9\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"236\" cy=\"158.6\" r=\"0.9\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><circle cx=\"220.3\" cy=\"162.5\" r=\"0.9\" fill=\"#DCE9F0\" opacity=\"0.7\"></circle><ellipse cx=\"222.9\" cy=\"155.2\" rx=\"14.9\" ry=\"7.4\" fill=\"none\" stroke=\"#7FB6C6\" stroke-width=\".6\" stroke-opacity=\".45\"></ellipse><circle cx=\"222.9\" cy=\"155.2\" r=\"3.2\" fill=\"#DCE9F0\"></circle><circle cx=\"222.9\" cy=\"155.2\" r=\"6.1\" fill=\"none\" stroke=\"#DCE9F0\" stroke-width=\".8\" stroke-opacity=\".7\"></circle></g><g data-n data-c=\"387.34 188.33\"><circle cx=\"378\" cy=\"182.9\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"390\" cy=\"181.3\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"400\" cy=\"185\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"400.5\" cy=\"191.2\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"391.1\" cy=\"195.2\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"378.9\" cy=\"194.1\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><circle cx=\"373.1\" cy=\"188.6\" r=\"1.2\" fill=\"#DCE9F0\" opacity=\"0.9\"></circle><ellipse cx=\"387.3\" cy=\"188.3\" rx=\"14.3\" ry=\"7.2\" fill=\"none\" stroke=\"#7FB6C6\" stroke-width=\".6\" stroke-opacity=\".45\"></ellipse><circle cx=\"387.3\" cy=\"188.3\" r=\"4.2\" fill=\"#DCE9F0\"></circle><circle cx=\"387.3\" cy=\"188.3\" r=\"8.1\" fill=\"none\" stroke=\"#DCE9F0\" stroke-width=\".8\" stroke-opacity=\".7\"></circle></g><g data-l><circle cx=\"307.9\" cy=\"149.1\" r=\"2\" fill=\"#D6F35C\"></circle><circle cx=\"307.9\" cy=\"149.1\" r=\"5\" fill=\"none\" stroke=\"#D6F35C\" stroke-width=\".7\" stroke-opacity=\".55\"></circle></g><g data-l><circle cx=\"406.4\" cy=\"157.7\" r=\"2\" fill=\"#D6F35C\"></circle><circle cx=\"406.4\" cy=\"157.7\" r=\"5\" fill=\"none\" stroke=\"#D6F35C\" stroke-width=\".7\" stroke-opacity=\".55\"></circle></g><g data-l><circle cx=\"385.8\" cy=\"179.2\" r=\"2\" fill=\"#D6F35C\"></circle><circle cx=\"385.8\" cy=\"179.2\" r=\"5\" fill=\"none\" stroke=\"#D6F35C\" stroke-width=\".7\" stroke-opacity=\".55\"></circle></g><g data-l><circle cx=\"433.3\" cy=\"55.4\" r=\"2\" fill=\"#D6F35C\"></circle><circle cx=\"433.3\" cy=\"55.4\" r=\"5\" fill=\"none\" stroke=\"#D6F35C\" stroke-width=\".7\" stroke-opacity=\".55\"></circle></g>";

// The disc is tilted: centre of the galaxy, tilt of its long axis and how flat it looks (measured from the orbit lines).
const CX = 358, CY = 128, PHI = (-17 * Math.PI) / 180, K = 0.394;

// Where a point on the disc ends up after turning th radians around the centre, in the plane of the disc.
function swing(x: number, y: number, th: number): [number, number] {
  const c = Math.cos(PHI), s = Math.sin(PHI);
  const dx = x - CX, dy = y - CY;
  const u = dx * c + dy * s, v = (-dx * s + dy * c) / K;
  const u2 = u * Math.cos(th) - v * Math.sin(th), v2 = (u * Math.sin(th) + v * Math.cos(th)) * K;
  return [CX + u2 * c - v2 * s, CY + u2 * s + v2 * c];
}

const motion: CardMotion = {
  id: 'porter-galaxy',
  svg,
  play(root, delay) {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return [];
    const out: Animation[] = [];
    // Each node travels a short arc along its orbit into place while it fades in.
    const STEPS = 8, SWING = (-26 * Math.PI) / 180;
    root.querySelectorAll<SVGGElement>('[data-n]').forEach((g, i) => {
      const [x, y] = (g.dataset.c || '0 0').split(' ').map(Number);
      const frames: Keyframe[] = [];
      for (let k = 0; k <= STEPS; k++) {
        const t = k / STEPS, e = 1 - Math.pow(1 - t, 3);
        const [px, py] = swing(x, y, SWING * (1 - e));
        frames.push({ transform: `translate(${(px - x).toFixed(2)}px, ${(py - y).toFixed(2)}px)`, opacity: Math.min(1, e * 1.5) });
      }
      out.push(g.animate(frames, { duration: 720, delay: delay + i * 100, easing: 'linear', fill: 'backwards' }));
    });
    // Then the lime points light up.
    root.querySelectorAll<SVGGElement>('[data-l]').forEach((g, i) => {
      g.style.transformBox = 'fill-box';
      g.style.transformOrigin = 'center';
      out.push(g.animate(
        [{ transform: 'scale(0.6)', opacity: 0 }, { transform: 'scale(1.25)', opacity: 1, offset: 0.55 }, { transform: 'scale(1)', opacity: 1 }],
        { duration: 400, delay: delay + 640 + i * 100, easing: EASE, fill: 'backwards' },
      ));
    });
    return out;
  },
};

export default motion;
